CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'uz' CHECK (language IN ('uz','ru','en')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'other', store_name TEXT, price NUMERIC(14,2), currency TEXT NOT NULL DEFAULT 'UZS', purchased_on DATE, warranty_months INTEGER CHECK (warranty_months IS NULL OR warranty_months BETWEEN 0 AND 240), warranty_end DATE, serial_number TEXT, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_products_user_created ON products(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_products_warranty_end ON products(user_id, warranty_end);
CREATE TABLE IF NOT EXISTS receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), product_id UUID NOT NULL UNIQUE REFERENCES products(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, data BYTEA NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 5242880), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id UUID REFERENCES products(id) ON DELETE CASCADE, kind TEXT NOT NULL, message TEXT NOT NULL, scheduled_for TIMESTAMPTZ, sent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
